import{_ as i,o as s,c as a,a5 as t}from"./chunks/framework.UjrY2eRK.js";const k=JSON.parse('{"title":"Enable the administration UI","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/self-hosting/administration.md","filePath":"deployment/self-hosting/administration.md","lastUpdated":1788169631000}'),n={name:"deployment/self-hosting/administration.md"};function o(l,e,r,p,h,d){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="enable-the-administration-ui" tabindex="-1">Enable the administration UI <a class="header-anchor" href="#enable-the-administration-ui" aria-label="Permalink to &quot;Enable the administration UI&quot;">​</a></h1><p>The administration UI is an opt-in feature of the single self-hosted Bun container. It is not available on Cloudflare and it does not add a second service, listener, or writable volume. The Angular application, same-origin operator API, and OIDC routes are served below <code>/admin/</code>; delivery continues at the existing Matrix endpoint.</p><h2 id="before-enabling" tabindex="-1">Before enabling <a class="header-anchor" href="#before-enabling" aria-label="Permalink to &quot;Before enabling&quot;">​</a></h2><p>You need:</p><ul><li>a stable HTTPS hostname for the gateway;</li><li>a confidential OIDC client in Pocket ID or Authentik;</li><li>one identity-provider group whose members may operate the gateway;</li><li>a random OIDC client secret and an independent random session secret;</li><li>a reverse proxy that owns TLS, HSTS, and response compression.</li></ul><p>Do not expose container port 3000 to a public interface. The supplied Compose file keeps its loopback binding when the administration override is applied.</p><h2 id="configure-the-compose-override" tabindex="-1">Configure the Compose override <a class="header-anchor" href="#configure-the-compose-override" aria-label="Permalink to &quot;Configure the Compose override&quot;">​</a></h2><p>Copy <code>.env.self-host-admin.example</code> to an ignored <code>.env.self-host-admin</code>. Create these additional files beside the four delivery secret files:</p><ul><li><code>secrets/admin_oidc_client_secret</code>, containing the provider client secret;</li><li><code>secrets/admin_session_secret</code>, containing at least 32 random bytes.</li></ul><p>Keep both files readable only by the deployment operator. Then start the base service and administration override together:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.self-host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.self-host-admin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.admin.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --detach</span></span></code></pre></div><p>The override sets the administration database to <code>/data/admin.sqlite</code> and its verified gateway-backup directory to <code>/data/backups</code>. On first successful enablement, the runtime validates separation from <code>gateway.sqlite</code>, applies the reviewed administration migrations, and loads the production browser assets. It does not alter the delivery schema.</p><p>Require all three checks:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --show-error</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://push.example.com/health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --show-error</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://push.example.com/admin/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --show-error</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://push.example.com/admin/sign-in</span></span></code></pre></div><p>If administration configuration, assets, OIDC, migrations, or <code>admin.sqlite</code> fail, <code>/admin/*</code> fails closed with a generic response. <code>/health</code> and Matrix notification delivery remain independent. Remove the override or set <code>TRINITY_PUSH_GATEWAY_ADMIN_ENABLED=false</code> to return to delivery-only mode; disabled mode ignores every other administration setting and requires no new secret.</p><h2 id="exact-urls" tabindex="-1">Exact URLs <a class="header-anchor" href="#exact-urls" aria-label="Permalink to &quot;Exact URLs&quot;">​</a></h2><p>For an origin of <code>https://push.example.com</code>, register these exact values:</p><table tabindex="0"><thead><tr><th>Purpose</th><th>URL</th></tr></thead><tbody><tr><td>Public origin</td><td><code>https://push.example.com</code></td></tr><tr><td>Authorization callback</td><td><code>https://push.example.com/admin/auth/callback</code></td></tr><tr><td>Post-logout return</td><td><code>https://push.example.com/admin/</code></td></tr></tbody></table><p>The public origin is an origin, not a path: no credentials, query, fragment, or trailing slash. The callback is matched exactly. Except for explicit loopback development, both issuer and public origin must use HTTPS.</p><h2 id="pocket-id" tabindex="-1">Pocket ID <a class="header-anchor" href="#pocket-id" aria-label="Permalink to &quot;Pocket ID&quot;">​</a></h2><p>Create a confidential OIDC client in Pocket ID with Authorization Code, PKCE, the exact callback and logout URLs above, and the allowed operator group. A new group-restricted Pocket ID client permits no users until its allowed group is assigned.</p><p>Use:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRINITY_PUSH_GATEWAY_ADMIN_OIDC_ISSUER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://id.example.com</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRINITY_PUSH_GATEWAY_ADMIN_OIDC_SCOPES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">openid profile email groups</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRINITY_PUSH_GATEWAY_ADMIN_OIDC_GROUP_CLAIM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">groups</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRINITY_PUSH_GATEWAY_ADMIN_OIDC_REQUIRED_GROUP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">push-gateway-operators</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRINITY_PUSH_GATEWAY_ADMIN_OIDC_TOKEN_ENDPOINT_AUTH_METHOD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client_secret_basic</span></span></code></pre></div><p>Pocket ID emits group names only when the <code>groups</code> scope is requested. Match the required group exactly, including case. Test with one member and one non-member before treating the deployment as ready.</p><h2 id="authentik" tabindex="-1">Authentik <a class="header-anchor" href="#authentik" aria-label="Permalink to &quot;Authentik&quot;">​</a></h2><p>Create an OAuth2/OpenID provider and application with:</p><ul><li>confidential client type, Authorization Code, and PKCE;</li><li>strict callback and logout URLs;</li><li>the built-in <code>openid</code>, <code>profile</code>, and <code>email</code> scope mappings;</li><li>groups included in the ID token; the default profile mapping supplies the group-name array;</li><li>per-provider issuer mode.</li></ul><p>If the application slug is <code>trinity-push-gateway</code>, use its complete issuer:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRINITY_PUSH_GATEWAY_ADMIN_OIDC_ISSUER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://auth.example.com/application/o/trinity-push-gateway/</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRINITY_PUSH_GATEWAY_ADMIN_OIDC_SCOPES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">openid profile email</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRINITY_PUSH_GATEWAY_ADMIN_OIDC_GROUP_CLAIM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">groups</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRINITY_PUSH_GATEWAY_ADMIN_OIDC_REQUIRED_GROUP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">push-gateway-operators</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRINITY_PUSH_GATEWAY_ADMIN_OIDC_TOKEN_ENDPOINT_AUTH_METHOD</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client_secret_post</span></span></code></pre></div><p>Do not use the Authentik base URL as the issuer. Confirm the issuer returned by its discovery document exactly matches the configured value, then test a group member and non-member.</p><h2 id="reverse-proxy-tls-hsts-and-compression" tabindex="-1">Reverse proxy, TLS, HSTS, and compression <a class="header-anchor" href="#reverse-proxy-tls-hsts-and-compression" aria-label="Permalink to &quot;Reverse proxy, TLS, HSTS, and compression&quot;">​</a></h2><p>The image deliberately does not bundle a reverse proxy or certificates. A minimal Caddy deployment is:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>push.example.com {</span></span>
<span class="line"><span>  encode zstd gzip</span></span>
<span class="line"><span>  header Strict-Transport-Security &quot;max-age=31536000; includeSubDomains&quot;</span></span>
<span class="line"><span>  reverse_proxy 127.0.0.1:3000</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Enable <code>includeSubDomains</code> only when every subdomain is permanently HTTPS. The proxy must preserve the original host and scheme so browser redirects resolve to the configured public origin. It must replace, not append, the client-address header, and its direct network must appear in <code>TRINITY_PUSH_GATEWAY_TRUSTED_PROXY_CIDRS</code> before forwarded addresses are trusted.</p><p>After deployment, verify the public HTTPS response carries HSTS and compression at the proxy, while the gateway supplies its CSP, anti-framing, no-sniff, referrer, permissions, cross-origin, and cache policies. Do not weaken the CSP to add remote fonts, scripts, analytics, or CDNs; the UI is intentionally self-contained.</p><h2 id="credential-rotation" tabindex="-1">Credential rotation <a class="header-anchor" href="#credential-rotation" aria-label="Permalink to &quot;Credential rotation&quot;">​</a></h2><p>Rotate either secret by replacing its Docker secret file and recreating the container. Rotating the session secret immediately invalidates every local Operator Session. Rotating the OIDC client secret blocks new login until the provider and gateway agree, but it does not expand an existing session&#39;s lifetime. There is no live reload and no local break-glass login.</p><p>Continue with <a href="/trinity-push-gateway/next/operations/administration.html">administration operations and recovery</a> and <a href="/trinity-push-gateway/next/operations/backup-and-restore.html">backup scope</a>.</p>`,38)])])}const u=i(n,[["render",o]]);export{k as __pageData,u as default};
